// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _test(address nonOwner, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(msg.sender != c.Owner());
        vm.assume(nonOwner != c.Owner());
        vm.assume(address(this).balance >= amount);
        try c.Command{value: amount}(nonOwner, "") {} catch { return; }
        uint256 beforeBal = address(nonOwner).balance;
        bool ok = true;
        try c.withdraw() { } catch { ok = false; }
        uint256 afterBal = address(nonOwner).balance;
        assertTrue(!ok || afterBal == beforeBal);
    }

    function testFuzz_test(address nonOwner, uint256 amount) public {
        _test(nonOwner, amount);
    }

    receive() external payable {}
}
